@Test
void enrich_filtersInactiveItems() {
    Item item = mock(Item.class);
    when(item.active()).thenReturn(false);
    Repository repo = mock(Repository.class);
    when(repo.load(1L)).thenReturn(item);
    Enrichment enrichment = new Enrichment();
    assertTrue(enrichment.enrich(List.of(1L), repo).isEmpty());
}

@Test
void enrich_filtersItemsWithDisabledOwner() {
    Owner owner = mock(Owner.class);
    when(owner.enabled()).thenReturn(false);
    Item item = mock(Item.class);
    when(item.active()).thenReturn(true);
    when(item.owner()).thenReturn(owner);
    Repository repo = mock(Repository.class);
    when(repo.load(1L)).thenReturn(item);
    Enrichment enrichment = new Enrichment();
    assertTrue(enrichment.enrich(List.of(1L), repo).isEmpty());
}

